**feedbackContext.js**
```js
import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedback, setFeedback] = useState({
    questions: [
      { id: 1, question: 'How easy was it to find the course material?' },
      { id: 2, question: 'How helpful were the instructors?' },
      { id: 3, question: 'How engaging was the coursework?' },
    ],
    answers: {},
  });

  const handleSubmit = (event) => {
    event.preventDefault();
    console.log(feedback.answers);
  };

  const handleAnswerChange = (id, answer) => {
    setFeedback((prevFeedback) => ({
      ...prevFeedback,
      answers: { ...prevFeedback.answers, [id]: answer },
    }));
  };

  return (
    <FeedbackContext.Provider value={{ feedback, handleSubmit, handleAnswerChange }}>
      {children}
    </FeedbackContext.Provider>
  );
};

export { FeedbackProvider, FeedbackContext };
```
This context provides the `feedback` state, which is an object containing an array of questions and an object to store the answers. It also provides two functions: `handleSubmit` to submit the feedback form, and `handleAnswerChange` to update the answers when a user selects a different answer.

**App.js**
