import React, { useContext } from 'react';
import { FeedbackContext } from './feedbackContext';

function FeedbackForm() {
  const { feedback, handleSubmit, handleAnswerChange } = useContext(FeedbackContext);

  return (
    <form onSubmit={handleSubmit}>
      {feedback.questions.map((question) => (
        <div key={question.id}>
          <h2>{question.question}</h2>
          <select value={feedback.answers[question.id]} onChange={(event) => handleAnswerChange(question.id, event.target.value)}>
            <option value="1">Strongly disagree</option>
            <option value="2">Disagree</option>
            <option value="3">Neutral</option>
            <option value="4">Agree</option>
            <option value="5">Strongly agree</option>
          </select>
        </div>
      ))}
      <button type="submit">Submit Feedback</button>
    </form>
  );
}

export default FeedbackForm;
```
